'use strict';

const fs = require('fs');

function fail(message) {
  throw new Error(message);
}

function readUnsigned(buffer, offset, size, littleEndian) {
  if (!Number.isSafeInteger(offset) || offset < 0 || offset + size > buffer.length) {
    fail('ELF field is outside the file');
  }

  let value = 0n;
  if (littleEndian) {
    for (let index = size - 1; index >= 0; index -= 1) {
      value = (value << 8n) | BigInt(buffer[offset + index]);
    }
  } else {
    for (let index = 0; index < size; index += 1) {
      value = (value << 8n) | BigInt(buffer[offset + index]);
    }
  }
  return value;
}

function asSafeNumber(value, description) {
  if (value > BigInt(Number.MAX_SAFE_INTEGER)) {
    fail(`${description} is too large`);
  }
  return Number(value);
}

function extractMemory(filePath) {
  const buffer = fs.readFileSync(filePath);
  if (buffer.length < 16 || buffer[0] !== 0x7f || buffer.toString('ascii', 1, 4) !== 'ELF') {
    fail('input is not an ELF file');
  }

  const elfClass = buffer[4];
  const dataEncoding = buffer[5];
  if (elfClass !== 1 && elfClass !== 2) {
    fail('unsupported ELF class');
  }
  if (dataEncoding !== 1 && dataEncoding !== 2) {
    fail('unsupported ELF byte order');
  }

  const littleEndian = dataEncoding === 1;
  const wordSize = elfClass === 2 ? 8 : 4;
  const field = (offset, size = wordSize) =>
    readUnsigned(buffer, offset, size, littleEndian);

  const programHeaderOffset = asSafeNumber(field(elfClass === 2 ? 32 : 28, wordSize), 'program header offset');
  const programHeaderSize = asSafeNumber(field(elfClass === 2 ? 54 : 42, 2), 'program header entry size');
  const programHeaderCount = asSafeNumber(field(elfClass === 2 ? 56 : 44, 2), 'program header count');

  const minimumProgramHeaderSize = elfClass === 2 ? 56 : 32;
  if (programHeaderSize < minimumProgramHeaderSize) {
    fail('invalid ELF program header size');
  }
  if (programHeaderCount !== 0 && programHeaderOffset > buffer.length - programHeaderSize * programHeaderCount) {
    fail('program headers are outside the file');
  }

  const memory = Object.create(null);
  const PT_LOAD = 1n;

  for (let headerIndex = 0; headerIndex < programHeaderCount; headerIndex += 1) {
    const headerOffset = programHeaderOffset + headerIndex * programHeaderSize;
    if (headerOffset > buffer.length - minimumProgramHeaderSize) {
      fail('program header is outside the file');
    }

    const type = field(headerOffset, 4);
    if (type !== PT_LOAD) {
      continue;
    }

    let fileOffset;
    let virtualAddress;
    let fileSize;
    let memorySize;
    if (elfClass === 2) {
      fileOffset = field(headerOffset + 8);
      virtualAddress = field(headerOffset + 16);
      fileSize = field(headerOffset + 32);
      memorySize = field(headerOffset + 40);
    } else {
      fileOffset = field(headerOffset + 4, 4);
      virtualAddress = field(headerOffset + 8, 4);
      fileSize = field(headerOffset + 16, 4);
      memorySize = field(headerOffset + 20, 4);
    }

    if (fileSize > memorySize) {
      fail('load segment has a file size larger than its memory size');
    }

    const fileOffsetNumber = asSafeNumber(fileOffset, 'load segment file offset');
    const fileSizeNumber = asSafeNumber(fileSize, 'load segment file size');
    if (fileOffsetNumber > buffer.length - fileSizeNumber) {
      fail('load segment data is outside the file');
    }

    for (let wordOffset = 0n; wordOffset < memorySize; wordOffset += 4n) {
      let value = 0;
      for (let byteOffset = 0; byteOffset < 4; byteOffset += 1) {
        const segmentOffset = wordOffset + BigInt(byteOffset);
        if (segmentOffset < fileSize) {
          const fileIndex = fileOffsetNumber + asSafeNumber(segmentOffset, 'load segment byte offset');
          value += buffer[fileIndex] * (2 ** (8 * byteOffset));
        }
      }

      const address = (virtualAddress + wordOffset).toString();
      if (memory[address] === undefined) {
        memory[address] = value;
      }
    }
  }

  return memory;
}

if (process.argv.length !== 3) {
  console.error(`Usage: node ${process.argv[1]} <ELF file>`);
  process.exitCode = 2;
} else {
  try {
    process.stdout.write(`${JSON.stringify(extractMemory(process.argv[2]))}\n`);
  } catch (error) {
    console.error(error instanceof Error ? error.message : String(error));
    process.exitCode = 1;
  }
}

